def merge_intervals(intervals):
    if not intervals:
        return []
    sorted_intervals = sorted(intervals, key=lambda x: (x[0], x[1]))
    merged = [list(sorted_intervals[0])]
    for start, end in sorted_intervals[1:]:
        if start <= merged[-1][1]:
            merged[-1][1] = max(merged[-1][1], end)
        else:
            merged.append([start, end])
    return merged

import heapq


def toposort(nodes, edges):
    unique_edges = set(edges)
    adj = {node: set() for node in nodes}
    in_degree = {node: 0 for node in nodes}

    for src, dst in unique_edges:
        adj[src].add(dst)
        in_degree[dst] += 1

    heap = [node for node in nodes if in_degree[node] == 0]
    heapq.heapify(heap)

    result = []
    while heap:
        node = heapq.heappop(heap)
        result.append(node)
        for neighbor in adj[node]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                heapq.heappush(heap, neighbor)

    if len(result) != len(nodes):
        raise ValueError("Cycle detected")

    return result

def stable_batches(items, limit):
    if limit <= 0:
        raise ValueError
    for _, w in items:
        if w <= 0 or w > limit:
            raise ValueError
    batches = []
    current = []
    total = 0
    for name, w in items:
        if total + w > limit:
            batches.append(current)
            current = []
            total = 0
        current.append(name)
        total += w
    if current:
        batches.append(current)
    return batches

import re


def parse_env(text):
    result = {}
    key_re = re.compile(r'^[A-Za-z_][A-Za-z0-9_]*$')

    for line in text.splitlines():
        stripped = line.strip()
        if not stripped or stripped.startswith('#'):
            continue

        if '=' not in stripped:
            raise ValueError(f"Invalid line (no '='): {stripped!r}")

        key, value = stripped.split('=', 1)
        key = key.strip()
        value = value.strip()

        if not key_re.match(key):
            raise ValueError(f"Invalid key: {key!r}")

        if len(value) >= 2 and value[0] == value[-1] and value[0] in ("'", '"'):
            value = value[1:-1]

        result[key] = value

    return result

def parse_sse(chunks):
    raw = b''.join(chunks)
    text = raw.decode('utf-8')
    text = text.replace('\r\n', '\n')
    lines = text.split('\n')

    events = []
    data_lines = []

    for line in lines:
        if line == '':
            if data_lines:
                data = '\n'.join(data_lines)
                if data == '[DONE]':
                    break
                events.append(data)
            data_lines = []
        elif line.startswith(':'):
            continue
        elif line.startswith('data:'):
            value = line[5:]
            if value.startswith(' '):
                value = value[1:]
            data_lines.append(value)
        else:
            continue

    return events

def fifo_admit(active, queued, budget, slots):
    for r in queued:
        if r > budget:
            raise ValueError(f"reservation {r} exceeds whole budget {budget}")

    tokens_remaining = budget - sum(active)
    slots_remaining = slots - len(active)

    admitted = []
    i = 0
    for r in queued:
        if slots_remaining >= 1 and tokens_remaining >= r:
            admitted.append(r)
            tokens_remaining -= r
            slots_remaining -= 1
            i += 1
        else:
            break

    remaining = queued[i:]
    return (admitted, remaining)
